module radix2_div (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output wire [15:0] result
);

reg [15:0] sr;
reg [3:0] cnt;
reg [7:0] neg_divisor;
reg start_cnt;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        sr <= 0;
        cnt <= 0;
        neg_divisor <= 0;
        start_cnt <= 0;
        res_valid <= 0;
    end else begin
        if (opn_valid && !res_valid) begin
            if (sign) begin
                sr[15:8] <= ~dividend + 1;
                sr[7:0] <= dividend;
                neg_divisor <= ~divisor + 1;
            end else begin
                sr[15:8] <= dividend;
                sr[7:0] <= dividend;
                neg_divisor <= divisor;
            end
            cnt <= 1;
            start_cnt <= 1;
            res_valid <= 1;
        end else if (start_cnt) begin
            if (cnt == 8) begin
                cnt <= 0;
                start_cnt <= 0;
            end else begin
                cnt <= cnt + 1;
                if (sr >= {neg_divisor, 8'b0}) begin
                    sr <= sr - {neg_divisor, 8'b0};
                    sr[15:8] <= sr[15:8] + 1;
                end
                sr = {sr[14:0], 1'b0};
            end
        end else begin
            res_valid <= 0;
        end
    end
end

assign result = {sr[15:8], sr[7:0]};

endmodule
